solutions.javascript:
const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tok = lines.join(' ').split(/\s+/).filter(s => s.length).map(Number);
const n = tok[0];
const par = [0, 0], w = [0, 0];
for (let v = 2; v <= n; v++) {
  par.push(tok[1 + 2 * (v - 2)]);
  w.push(tok[2 + 2 * (v - 2)]);
}
const down = new Array(n + 1).fill(0);
let best = 0;
for (let v = n; v >= 2; v--) {
  const p = par[v], branch = down[v] + w[v];
  best = Math.max(best, down[p] + branch);
  down[p] = Math.max(down[p], branch);
}
console.log(best);

