import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] par = new int[n + 1];
        long[] w = new long[n + 1];
        for (int v = 2; v <= n; v++) {
            par[v] = sc.nextInt();
            w[v] = sc.nextLong();
        }
        long[] down = new long[n + 1];
        long best = 0;
        for (int v = n; v >= 2; v--) {
            int p = par[v];
            long branch = down[v] + w[v];
            best = Math.max(best, down[p] + branch);
            down[p] = Math.max(down[p], branch);
        }
        System.out.println(best);
    }
}

