#include <bits/stdc++.h>
using namespace std;
int main() {
    int n;
    scanf("%d", &n);
    vector<int> par(n + 1, 0);
    vector<long long> w(n + 1, 0), down(n + 1, 0);
    for (int v = 2; v <= n; v++) scanf("%d %lld", &par[v], &w[v]);
    long long best = 0;
    for (int v = n; v >= 2; v--) {
        int p = par[v];
        long long branch = down[v] + w[v];
        best = max(best, down[p] + branch);
        down[p] = max(down[p], branch);
    }
    printf("%lld\n", best);
    return 0;
}
